INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34511, 'Romans 11:3', 'Romans', 11, 3, '«څښتنه، هغوی ستا پیغمبران وژلي دي، ستا د قربانۍ ځایونه یې وران کړي دي او زه یوازې پاتې یم او هغوی هڅه کوي چې ما هم ووژني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_3.mp3', '', 1761754199, 1761754199),
(34512, 'Romans 11:4', 'Romans', 11, 4, 'خو خدای هغه ته څه ځواب ورکړ؟ هغه دا ځواب ورکړ: «ما د خپل ځان دپاره اووه زره کسان چې د بعل بت ته یې سجده نه ده کړې، ساتلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_4.mp3', '', 1761754199, 1761754199),
(34513, 'Romans 11:5', 'Romans', 11, 5, 'همدارنګه په دې اوسنۍ زمانه کې هم یو شمېر خلک پاتې دي چې د خدای په فضل سره غوره شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_5.mp3', '', 1761754199, 1761754199),
(34514, 'Romans 11:6', 'Romans', 11, 6, 'خو که چېرې دا د فضل په وسیله وي، نو بیا د انسان د عملونو په وسیله نه دی. که نه، نو بیا فضل کومه معنی نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_6.mp3', '', 1761754199, 1761754199),
(34515, 'Romans 11:7', 'Romans', 11, 7, 'نو بیا دا څه معنی؟ د اسراییلو خلک چې د کوم شي په لټه کې وو، هغه یې تر‌لاسه نه کړ. د خدای غوره شویو کسانو تر‌لاسه کړ، خو د نورو زړونه سخت شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_7.mp3', '', 1761754199, 1761754199),
(34516, 'Romans 11:8', 'Romans', 11, 8, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي: خدای هغوی په روحاني درانه خوب ویده کړل چې تر نن ورځې پورې نه څه لیدلی شي او نه څه اورېدلی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_8.mp3', '', 1761754199, 1761754199),
(34517, 'Romans 11:9', 'Romans', 11, 9, 'او داود وایي: پرېږده چې دسترخوان یې ورته تیلک او دام شي او تیږه ورته داسې شي چې پرې وښوییږي او د خپلو کارونو سزا وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_9.mp3', '', 1761754199, 1761754199),
(34518, 'Romans 11:10', 'Romans', 11, 10, 'پرېږده چې سترګې یې ړندې شي چې هېڅ ونه ویني او ملاګانې یې د تل دپاره کړوپې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_10.mp3', '', 1761754199, 1761754199),
(34519, 'Romans 11:11', 'Romans', 11, 11, 'نو زه پوښتنه کوم، ایا هغوی داسې وښویېدل چې بیا به هېڅکله راپورته نه شي؟ هېڅکله نه، بلکې د هغوی د سرغړونې په سبب خلاصون د غیریهودیانو په برخه شو او له همدې امله د اسراییلو سره کینه پیدا شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_11.mp3', '', 1761754199, 1761754199),
(34520, 'Romans 11:12', 'Romans', 11, 12, 'اوس که چېرې د هغوی سرغړونه د دنیا د برکت سبب شوه او د هغوی روحاني ماتې د غیریهودیانو دپاره د برکت سبب شوه، نو بیا به د هغوی برکتونه نور څومره زیات شي چې کله ټول اسراییل په کې شامل شي. د غیر یهودیانو ژغورل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_12.mp3', '', 1761754199, 1761754199),
(34521, 'Romans 11:13', 'Romans', 11, 13, 'اوس تاسو غیریهودیانو ته وایم چې زه د غیریهودیانو دپاره رسول یم او په خپل کار باندې ویاړ کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_13.mp3', '', 1761754199, 1761754199),
(34522, 'Romans 11:14', 'Romans', 11, 14, 'ځکه کېدای شی چې په دې ډول وکولای شم د خپل قوم حسد او بخیلي راوپاروم او د هغوی څخه ځینې یې وژغورم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_14.mp3', '', 1761754199, 1761754199),
(34523, 'Romans 11:15', 'Romans', 11, 15, 'ځکه که د هغوی رد کېدل د دنیا سره د خدای د پخلا کېدلو سبب شو، نو د هغوی منل به لکه د مرګ نه د بیا راژوندي کېدلو په معنی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_15.mp3', '', 1761754199, 1761754199),
(34524, 'Romans 11:16', 'Romans', 11, 16, 'که چېرې د اوړو لومړنۍ پېړه چې خدای ته د نذرانې په توګه وړاندې کیږي، سپېڅلې وي، نو بیا ټوله خمیره هم سپېڅلي ده. او که د ونې ریښې سپېڅلې وي، نو څانګې یې هم سپېڅلې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_16.mp3', '', 1761754199, 1761754199),
(34525, 'Romans 11:17', 'Romans', 11, 17, 'خو که چېرې ځینې څانګې پرېکړل شي او ته چې د ځنګلي زیتون یوه څانګه وې، په نورو څانګو کې پیوند شوې او د اصلي زیتون د ونې په ګټوره ریښه کې شریک شوې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_17.mp3', '', 1761754199, 1761754199),
(34526, 'Romans 11:18', 'Romans', 11, 18, 'نو خپل ځان د نورو څانګو نه لوړ مه ګڼه. که چېرې خپل ځان لوړ ګڼې، نو یاد ساته چې ریښه په تا باندې ولاړه نه ده، بلکې ته په ریښې باندې ولاړ یې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_18.mp3', '', 1761754199, 1761754199),
(34527, 'Romans 11:19', 'Romans', 11, 19, 'خو ته به وایې: «څانګې د دې دپاره پرېکړل شوې چې زه په کې پیوند شم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_19.mp3', '', 1761754199, 1761754199),
(34528, 'Romans 11:20', 'Romans', 11, 20, 'دا رښتیا ده. هغوی د خپلې بې‌ایمانۍ له امله پرېکړل شوې، خو ته د ایمان په وسیله هلته پاتې کېږې. نو مغرور کېږه مه، بلکې ووېرېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_20.mp3', '', 1761754199, 1761754199),
(34529, 'Romans 11:21', 'Romans', 11, 21, 'ځکه که خدای هغه طبیعي څانګې په خپل ځای پرېنښودلې، نو تا به هم پرېنږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_21.mp3', '', 1761754199, 1761754199),
(34530, 'Romans 11:22', 'Romans', 11, 22, 'نو د خدای مهرباني او سخت قضاوت په پام کې ونیسه. خدای د هغو خلکو په وړاندې سختګیره دی چې لېرې لوېدلي دي، خو ستا په وړاندې مهربانه دی، که چېرې ته د هغه په مهربانۍ کې پاتې شې. که نه، نو ته به هم پرېکړل شې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_22.mp3', '', 1761754199, 1761754199),
(34531, 'Romans 11:23', 'Romans', 11, 23, 'که چېرې یهودیان په بې‌ایمانۍ کې پاتې نه شي، نو هغوی به بیا پیوند کړل شي، ځکه چې خدای قدرت لري چې هغوی یوځل بیا سره پیوند کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_23.mp3', '', 1761754199, 1761754199),
(34532, 'Romans 11:24', 'Romans', 11, 24, 'ځکه که چېرې تاسو غیریهودیان د ځنګلي زیتون د ونې نه پرېکړل شوي یئ او د خپل فطرت په خلاف د اصلي زیتون د ونې سره پیوند شوي یئ، نو بیا به هغه اصلي څانګې څومره په اسانۍ سره پیوند شي چې د اصلي زیتون د ونې خپلې څانګې دي. په ټولو باندې د خدای رحم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_24.mp3', '', 1761754199, 1761754199),
(34533, 'Romans 11:25', 'Romans', 11, 25, 'ای خویندو او ورونو! زه نه غواړم چې تاسو د دې پټ راز نه بې‌خبره پاتې شئ او په خپلې پوهې باندې مغرور شئ. د ځینو اسراییلیانو زړونه سخت شوي دي او دا به تر هغه وخته پورې دوام وکړي، ترڅو د هغو غیریهودیانو شمېر پوره شي چې خلاصون مومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_25.mp3', '', 1761754199, 1761754199),
(34534, 'Romans 11:26', 'Romans', 11, 26, 'په دې ډول به ټول اسراییل خلاصون ومومي. لکه څنګه چې لیکل شوي دي: خلاصوونکی به د صهیون څخه راشي او هغه به د یعقوب د نسل څخه بې‌دیني لېرې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_26.mp3', '', 1761754199, 1761754199),
(34535, 'Romans 11:27', 'Romans', 11, 27, 'زه به د هغوی سره لوظ وکړم چې د هغوی ګناهونه لېرې کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_27.mp3', '', 1761754199, 1761754199),
(34536, 'Romans 11:28', 'Romans', 11, 28, 'د زېري په خاطر یهودیان د خدای دښمنان شول او دا ستاسو په ګټه دی. د خدای د خوښې له امله هغوی اوس هم خدای ته د هغوی د نیکونو ابراهیم، اسحاق او یعقوب په خاطر ګران دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_28.mp3', '', 1761754199, 1761754199),
(34537, 'Romans 11:29', 'Romans', 11, 29, 'ځکه چې د خدای نعمتونه او بلنه نه‌بدلېدونکي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_29.mp3', '', 1761754199, 1761754199),
(34538, 'Romans 11:30', 'Romans', 11, 30, 'لکه څنګه چې تاسو غیریهودیانو یو وخت د خدای په وړاندې نافرماني کوله، خو اوس په تاسو باندې د یهودیانو د نافرمانۍ له امله رحم وشو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_30.mp3', '', 1761754199, 1761754199),
(34539, 'Romans 11:31', 'Romans', 11, 31, 'نو اوس هغوی نافرماني کوي او په تاسو باندې د خدای رحم وشو، نو له دې امله په هغوی باندې به هم د هغه رحم وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_31.mp3', '', 1761754199, 1761754199),
(34540, 'Romans 11:32', 'Romans', 11, 32, 'خدای ټول خلک په نافرمانۍ کې راګېر کړل، ترڅو په ټولو باندې رحم وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_32.mp3', '', 1761754199, 1761754199),
(34541, 'Romans 11:33', 'Romans', 11, 33, 'واه، د خدای شتمني څومره زیاته ده او د هغه حکمت او پوهه څومره ژوره ده! د هغه قضاوتونه څومره پټ او د هغه په لارو پوهېدل څومره سخت دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_33.mp3', '', 1761754199, 1761754199),
(34542, 'Romans 11:34', 'Romans', 11, 34, 'ځکه د خدای په کلام کې لیکل شوي دي: څوک کولای شي چې د څښتن په فکرونو باندې پوه شي؟ یا څوک کولای شي چې هغه ته مشوره ورکړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_34.mp3', '', 1761754199, 1761754199),
(34543, 'Romans 11:35', 'Romans', 11, 35, 'یا چا خدای ته کوم شی ورکړی دی چې بېرته یې ترې واخلي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_35.mp3', '', 1761754199, 1761754199),
(34544, 'Romans 11:36', 'Romans', 11, 36, 'ځکه چې ټول شیان د هغه له خوا دي او د هغه په وسیله پیدا شوي دي او د هغه دپاره دي. د هغه جلال دې تل ترتله وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_36.mp3', '', 1761754199, 1761754199),
(34545, 'Ephesians 3:1', 'Ephesians', 3, 1, 'په همدې دلیل زه پولوس چې ستاسو غیریهودیانو او د عیسی مسیح په خاطر بندي یم، تاسو دپاره دعا کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_1.mp3', '', 1761754199, 1761754199),
(34546, 'Ephesians 3:2', 'Ephesians', 3, 2, 'تاسو به خامخا اورېدلي وي چې خدای د خپل فضل له مخې ماته دا وظیفه راکړې ده چې ستاسو دپاره یې سرته ورسوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_2.mp3', '', 1761754199, 1761754199),
(34547, 'Ephesians 3:3', 'Ephesians', 3, 3, 'لکه څنګه چې ما تاسو ته مخکې په لنډه توګه ولیکل، دا پټ راز خدای په خپله د الهام په وسیله ماته ښکاره کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_3.mp3', '', 1761754199, 1761754199),
(34548, 'Ephesians 3:4', 'Ephesians', 3, 4, 'ما چې تاسو ته څه لیکلي دي، که چېرې تاسو هغه ولولئ، نو پوه به شئ چې زه د مسیح د پټ راز څخه خبر یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_4.mp3', '', 1761754199, 1761754199),
(34549, 'Ephesians 3:5', 'Ephesians', 3, 5, 'دا راز په پخوا زمانو کې انسانانو ته داسې نه ؤ ښکاره شوی لکه څنګه چې اوس د روح القدس په وسیله د خدای سپېڅلو رسولانو او پیغمبرانو ته ښکاره شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_5.mp3', '', 1761754199, 1761754199),
(34550, 'Ephesians 3:6', 'Ephesians', 3, 6, 'هغه راز دا دی چې غیریهودیان د زېري په وسیله د یهودیانو سره په میراث کې شریک دي، دواړه د یو بدن غړي او په هغې وعدې کې شریک دي چې خدای په عیسی مسیح کې زمونږ سره کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_6.mp3', '', 1761754199, 1761754199),
(34551, 'Ephesians 3:7', 'Ephesians', 3, 7, 'زه د خدای د فضل د نعمت په وسیله چې ماته یې د خپل قدرت په کارولو سره راکړی دی، د زېري خدمتګار شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_7.mp3', '', 1761754199, 1761754199),
(34552, 'Ephesians 3:8', 'Ephesians', 3, 8, 'که څه هم زه د خدای په ټولو خلکو کې کوچنی یم، خو دا فضل یې په ما کړی دی چې زه غیریهودیانو ته د مسیح د بې‌حده شتمنۍ زېری ورکړم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_8.mp3', '', 1761754199, 1761754199),
(34553, 'Ephesians 3:9', 'Ephesians', 3, 9, 'او هغه پټه نقشه ټولو خلکو ته ښکاره کړم چې خدای د ټولو شیانو خالق دا راز د ازل نه پټ ساتلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_9.mp3', '', 1761754199, 1761754199),
(34554, 'Ephesians 3:10', 'Ephesians', 3, 10, 'د خدای مقصد دا ؤ چې اوس د خپل حکمت مختلف اړخونه د کلیسا په وسیله حاکمانو او د واک خاوندانو ته په اسماني ځایونو کې ښکاره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_10.mp3', '', 1761754199, 1761754199),
(34555, 'Ephesians 3:11', 'Ephesians', 3, 11, 'د دې پټ راز ښکاره کول هغه ابدي مقصد ؤ چې خدای زمونږ د څښتن عیسی مسیح په وسیله عملي کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_11.mp3', '', 1761754199, 1761754199),
(34556, 'Ephesians 3:12', 'Ephesians', 3, 12, 'نو مونږ په مسیح کې او په هغه باندې د ایمان په وسیله په زړورتیا او باور سره کولای شو چې د خدای حضور ته ورشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_12.mp3', '', 1761754199, 1761754199),
(34557, 'Ephesians 3:13', 'Ephesians', 3, 13, 'نو زه ستاسو نه غوښتنه کوم چې زما د کړاوونو په خاطر چې ستاسو دپاره یې تېروم مه بې‌زړه کېږئ، ځکه چې دا ستاسو د سرلوړۍ سبب کیږي. د عیسی مسیح مینه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_13.mp3', '', 1761754199, 1761754199),
(34558, 'Ephesians 3:14', 'Ephesians', 3, 14, 'په همدې دلیل زه د پلار په مخکې په ګونډو کېږم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_14.mp3', '', 1761754199, 1761754199),
(34559, 'Ephesians 3:15', 'Ephesians', 3, 15, 'د هغه چا په مخکې چې هره کورنۍ په اسمان او ځمکه کې خپل نوم د هغه څخه اخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_15.mp3', '', 1761754199, 1761754199),
(34560, 'Ephesians 3:16', 'Ephesians', 3, 16, 'زه دعا کوم چې هغه تاسو ته د خپل لوی جلال له مخې هغه قوت درکړي چې تاسو په خپل باطن کې د هغه د روح په وسیله قوي شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_16.mp3', '', 1761754199, 1761754199),
(34561, 'Ephesians 3:17', 'Ephesians', 3, 17, 'همدارنګه زه دعا کوم چې ستاسو د ایمان په وسیله مسیح ستاسو په زړونو کې واوسیږي. زه دعا کوم چې د خدای مینه په تاسو کې ریښې وځغلوي او د مینې په بنیاد ودان شئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_17.mp3', '', 1761754199, 1761754199),
(34562, 'Ephesians 3:18', 'Ephesians', 3, 18, 'ترڅو تاسو د خدای د ټولو خلکو سره یوځای دا توان ولرئ چې په دې پوه شئ چې د مسیح مینه څومره پراخه، اوږده، اوچته او ژوره ده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_18.mp3', '', 1761754199, 1761754199),
(34563, 'Ephesians 3:19', 'Ephesians', 3, 19, 'ترڅو د مسیح هغه مینه وپېژنئ چې د پوهې نه لوړه ده او تاسو په پوره توګه د خدای د کامل فطرت او خوی نه ډک شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_19.mp3', '', 1761754199, 1761754199),
(34564, 'Ephesians 3:20', 'Ephesians', 3, 20, 'جلال دې وي هغه چاته چې په خپل قدرت سره کولای شي د هغه څه نه چې مونږ ډېر زیات غواړو او ګومان یې کوو په مونږ کې زیات کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_20.mp3', '', 1761754199, 1761754199),
(34565, 'Ephesians 3:21', 'Ephesians', 3, 21, 'هغه ته دې په کلیسا او په عیسی مسیح کې تل ترتله په ټولو نسلونو کې جلال وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians3_verse_21.mp3', '', 1761754199, 1761754199),
(34566, 'Revelation 6:1', 'Revelation', 6, 1, 'بیا مې ولیدل چې وري د هغو اوو مهرونو څخه یو مهر مات کړ. له هغې وروسته مې د هغو څلورو اسماني موجوداتو څخه د یو اواز چې د تندر په شان ؤ، واورېد چې ویل یې: «راشه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_1.mp3', '', 1761754199, 1761754199),
(34567, 'Revelation 6:2', 'Revelation', 6, 2, 'ما وکتل او ومې لیدل چې هلته یو سپین اس ؤ او د هغه کس سره چې ورباندې سپور ؤ یوه لینده وه او هغه ته یو تاج ورکړل شو او هغه ووت چې بری ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_2.mp3', '', 1761754199, 1761754199),
(34568, 'Revelation 6:3', 'Revelation', 6, 3, 'کله چې وري دوهم مهر مات کړ، نو ما واورېدل چې دوهم ژوندي مخلوق ویل: «راشه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_3.mp3', '', 1761754199, 1761754199),
(34569, 'Revelation 6:4', 'Revelation', 6, 4, 'یو بل اس راووت چې تک سور رنګ یې درلود او په هغه باندې سپاره کس ته قدرت ورکړل شو چې د ځمکې د مخ نه سوله او ارامي یوسي، ترڅو خلک یو بل سره ووژني. هغه ته یوه غټه توره ورکړل شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_4.mp3', '', 1761754199, 1761754199),
(34570, 'Revelation 6:5', 'Revelation', 6, 5, 'کله چې وري درېم مهر مات کړ، نو ما واورېدل چې درېم اسماني موجود ویل: «راشه!» ما وکتل او یو تور اس مې ولیده او په هغه باندې د سپور کس په لاس کې یوه ترازو وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_5.mp3', '', 1761754199, 1761754199),
(34571, 'Revelation 6:6', 'Revelation', 6, 6, 'د هغو څلورو اسماني موجوداتو له منځ نه مې یو اواز واورېد چې ویل یې: «د یو مزدور ورځنۍ مزدوري به یو کیلو غنم او یا درې کیلو اوربشې وي. خو د زیتون ونې او د انګورو تاک ته زیان مه رسوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_6.mp3', '', 1761754199, 1761754199),
(34572, 'Revelation 6:7', 'Revelation', 6, 7, 'کله چې وري څلورم مهر مات کړ، نو ما واورېدل چې څلورم اسماني موجود ویل: «راشه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_7.mp3', '', 1761754199, 1761754199),
(34573, 'Revelation 6:8', 'Revelation', 6, 8, 'ما وکتل او ومې لیدل چې هلته یو اس ؤ چې رنګ یې زیړ ؤ او څوک چې په هغه اس باندې سپور ؤ د هغه نوم مرګ ؤ او قبر ورپسې ډېر نژدې روان ؤ. هغوی ته د ځمکې د څلورمې برخې واک او اختیار ورکړل شوی ؤ چې په توره، قحطۍ، د طاعون په ناروغۍ او ځنګلي ځناورو باندې خلک مړه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_8.mp3', '', 1761754199, 1761754199),
(34574, 'Revelation 6:9', 'Revelation', 6, 9, 'کله چې وري پنځم مهر مات کړ، نو ما د قربانۍ د ځای لاندې د هغو خلکو روحونه ولیدل چې د خدای د کلام او په خپلې شاهدۍ کې د وفادارۍ په خاطر وژل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_9.mp3', '', 1761754199, 1761754199),
(34575, 'Revelation 6:10', 'Revelation', 6, 10, 'هغوی په لوړ اواز نارې کړې: «ای څښتن تعالی، سپېڅلی او رښتینی خدایه! ترڅو پورې به د نړۍ د خلکو په هکله قضاوت نه کوې او د هغوی څخه به زمونږ د وینې بدل نه اخلې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_10.mp3', '', 1761754199, 1761754199),
(34576, 'Revelation 6:11', 'Revelation', 6, 11, 'هغوی هر یو ته سپینه چپنه ورکړل شوه او ورته وویل شول چې تر هغې پورې لږ نور صبر وکړئ، ترڅو ستاسو د ورونو او د خدای د نورو خدمتګارانو شمېر چې ستاسو په شان باید ووژل شي، پوره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_11.mp3', '', 1761754199, 1761754199),
(34577, 'Revelation 6:12', 'Revelation', 6, 12, 'بیا ما وکتل او ومې لیدل چې وري شپږم مهر مات کړ او یوه سخته زلزله وشوه او لمر د ویر د کالیو په شان تور شو او سپوږمۍ لکه د وینې په شان سره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_12.mp3', '', 1761754199, 1761754199),
(34578, 'Revelation 6:13', 'Revelation', 6, 13, 'ستوري د اسمان نه داسې راولوېدل لکه څنګه چې خام انځران د سخت باد له امله د ونې نه په ځمکه رالویږي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_13.mp3', '', 1761754199, 1761754199),
(34579, 'Revelation 6:14', 'Revelation', 6, 14, 'او اسمان داسې فنا شو لکه څنګه چې طومار سره تاو او راتاو شي او هر غر او هره جزیره له خپله ځایه وخوځېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_14.mp3', '', 1761754199, 1761754199),
(34580, 'Revelation 6:15', 'Revelation', 6, 15, 'نو بیا د ځمکې پاچاهانو، حاکمانو، قومندانانو، شتمنو، زورواکانو او ټولو خلکو که هغه غلامان وو یا ازاد، خپل ځانونه په غارونو او د غرونو د ګټانو په منځ کې پټ کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_15.mp3', '', 1761754199, 1761754199),
(34581, 'Revelation 6:16', 'Revelation', 6, 16, 'هغوی غرونو او ګټانو ته غږ وکړ: «په مونږ راولوېږئ او د هغه کس له نظره چې په تخت باندې ناست دی او د وري له غضب نه مو پټ کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_16.mp3', '', 1761754199, 1761754199),
(34582, 'Revelation 6:17', 'Revelation', 6, 17, 'ځکه چې د خدای او د وري د لوی غضب ورځ رارسېدلې ده، څوک کولای شي د هغه په وړاندې ودریږي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation6_verse_17.mp3', '', 1761754199, 1761754199),
(34583, 'Luke 11:1', 'Luke', 11, 1, 'یوه ورځ عیسی په یو ځای کې دعا کوله. کله چې هغه خپله دعا خلاصه کړه، نو د شاګردانو څخه یو تن هغه ته وویل: «ای استاذه! لکه څنګه چې یحیی خپلو شاګردانو ته دعا کول زده کړي وو، ته یې هم مونږ ته رازده کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke11_verse_1.mp3', '', 1761754199, 1761754199),
(34584, 'Luke 11:2', 'Luke', 11, 2, 'عیسی هغوی ته وویل: «کله چې تاسو دعا کوئ، نو داسې ووایئ: ‹ای اسماني پلاره! ستا نوم دې پاک وي، ستا پاچاهي دې راشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke11_verse_2.mp3', '', 1761754199, 1761754199),
